function getManifest(){if(!manifestPromise)manifestPromise=json(preview?'technique-levels.json':'manifest.json').then(data=>{if(data.format!==1||!pickerLevels.every(l=>data.levels?.[l]?.chunks?.length))throw Error('manifest');manifest=data;if(preview){for(const l of previewLevels)for(const c of data.levels[l.id].chunks)for(const r of recent.values())if(c.ids.includes(r.id))r.previewLevel=l.id;persist();api.onRender(initial.values.join(''),state.values.every(Boolean)&&!Sudoku.conflicts(state.values).some(Boolean),state.values);}return data;}).catch(error=>{manifestPromise=null;throw error;});return manifestPromise;}
function getChunk(file){if(!/^(easy|medium|hard|expert)-\d+\.json$/.test(file))return Promise.reject(Error('chunk'));if(!cache.has(file))cache.set(file,json(file).catch(e=>{cache.delete(file);throw e;}));return cache.get(file);}
